import React, { useState } from 'react';
import { Pie, Bar } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import { sampleReceipts, budgetCategories, spendingTrends, categoryBreakdown } from '../../data/groceryData';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

function GroceryAnalyzer() {
  const [selectedReceipt, setSelectedReceipt] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState(0);
  const [analysisResults, setAnalysisResults] = useState(null);

  const processReceipt = (receipt) => {
    setIsProcessing(true);
    setProcessingStep(1);
    setSelectedReceipt(receipt);

    // Simulate AI processing steps
    setTimeout(() => {
      setProcessingStep(2);
      setTimeout(() => {
        setProcessingStep(3);
        setTimeout(() => {
          // Calculate analysis
          const total = receipt.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
          const categoryTotals = {};

          receipt.items.forEach(item => {
            if (!categoryTotals[item.category]) {
              categoryTotals[item.category] = 0;
            }
            categoryTotals[item.category] += item.price * item.quantity;
          });

          const topCategory = Object.entries(categoryTotals).reduce((a, b) => a[1] > b[1] ? a : b);
          const avgItemPrice = total / receipt.items.length;

          setAnalysisResults({
            total,
            itemCount: receipt.items.length,
            categoryTotals,
            topCategory: topCategory[0],
            topCategoryAmount: topCategory[1],
            avgItemPrice,
            chartData: categoryBreakdown(receipt.items)
          });

          setProcessingStep(4);
          setIsProcessing(false);
        }, 1000);
      }, 1000);
    }, 1000);
  };

  const getBudgetStatus = (category, amount) => {
    const budget = budgetCategories.find(b => 
      b.name.toLowerCase().includes(category.toLowerCase()) || 
      category.toLowerCase().includes(b.name.toLowerCase())
    );

    if (!budget) return null;

    const percentage = (amount / budget.limit) * 100;
    if (percentage > 100) return { status: 'Over Budget', color: 'red', percentage };
    if (percentage > 80) return { status: 'Warning', color: 'orange', percentage };
    return { status: 'Within Budget', color: 'green', percentage };
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'bottom',
        labels: { color: 'white' }
      }
    }
  };

  const barChartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
        labels: { color: 'white' }
      },
      title: {
        display: true,
        text: 'Monthly Spending Trends',
        color: 'white'
      }
    },
    scales: {
      y: {
        ticks: { color: 'white' },
        grid: { color: 'rgba(255,255,255,0.1)' }
      },
      x: {
        ticks: { color: 'white' },
        grid: { color: 'rgba(255,255,255,0.1)' }
      }
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Project Header */}
      <div className="bg-gradient-to-r from-green-600 to-emerald-600 rounded-2xl p-8 mb-8 text-white">
        <div className="flex items-center mb-4">
          <span className="text-6xl mr-4">🧾</span>
          <div>
            <h1 className="text-4xl font-bold mb-2">Grocery Receipt Analyzer</h1>
            <p className="text-xl">AI-Powered Grocery Bill Analysis & Expense Management System</p>
          </div>
        </div>
      </div>

      {/* Problem vs Solution */}
      <div className="grid md:grid-cols-2 gap-6 mb-8">
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">❌ Current System (Manual)</h3>
          <ul className="space-y-3 text-gray-200">
            <li className="flex items-start">
              <span className="mr-2">1.</span>
              <span>Manual entry of receipt items into expense tracking apps</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">2.</span>
              <span>Time-consuming categorization of purchases</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">3.</span>
              <span>Difficult to track spending patterns over time</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">4.</span>
              <span>No automated budget alerts or recommendations</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">5.</span>
              <span>Lost receipts mean lost expense records</span>
            </li>
          </ul>
        </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">✅ Proposed System (Automated)</h3>
          <ul className="space-y-3 text-gray-200">
            <li className="flex items-start">
              <span className="mr-2">1.</span>
              <span>Instant receipt scanning using OCR and AI</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">2.</span>
              <span>Automatic item categorization and price extraction</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">3.</span>
              <span>Visual spending analytics and trend analysis</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">4.</span>
              <span>Smart budget tracking with alerts</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">5.</span>
              <span>Cloud storage of all receipts for easy access</span>
            </li>
          </ul>
        </div>
      </div>

      {/* Receipt Upload Section */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-8 border border-white/20 mb-8">
        <h2 className="text-3xl font-bold text-white mb-6">🎯 Interactive Simulation</h2>

        {!selectedReceipt && (
          <>
            <div className="grid md:grid-cols-2 gap-6 mb-6">
              {/* Upload Option */}
              <div className="bg-gradient-to-br from-blue-600/30 to-purple-600/30 rounded-xl p-8 border-2 border-dashed border-white/30 text-center">
                <div className="text-6xl mb-4">📸</div>
                <h3 className="text-xl font-bold text-white mb-3">Upload Receipt Image</h3>
                <p className="text-gray-300 mb-4">Take a photo or upload an image of your receipt</p>
                <button className="bg-blue-500 hover:bg-blue-600 text-white px-6 py-3 rounded-lg font-semibold transition-all">
                  📤 Choose Image
                </button>
                <p className="text-gray-400 text-sm mt-3">Supports JPG, PNG, PDF</p>
              </div>

              {/* Sample Data Option */}
              <div className="bg-gradient-to-br from-green-600/30 to-teal-600/30 rounded-xl p-8 border-2 border-dashed border-white/30 text-center">
                <div className="text-6xl mb-4">📋</div>
                <h3 className="text-xl font-bold text-white mb-3">Use Sample Data</h3>
                <p className="text-gray-300 mb-4">Try the demo with pre-loaded sample receipts</p>
                <p className="text-white font-semibold mb-2">Choose a sample:</p>
              </div>
            </div>

            {/* Sample Receipt Cards */}
            <div className="grid md:grid-cols-3 gap-4">
              {sampleReceipts.map(receipt => (
                <div
                  key={receipt.id}
                  className="bg-white/10 hover:bg-white/20 rounded-lg p-6 border border-white/20 cursor-pointer transition-all duration-300 hover:transform hover:scale-105"
                  onClick={() => processReceipt(receipt)}
                >
                  <div className="flex items-center justify-between mb-3">
                    <h4 className="text-lg font-bold text-white">{receipt.name}</h4>
                    <span className="text-2xl">🛒</span>
                  </div>
                  <p className="text-gray-300 text-sm mb-2">Store: {receipt.store}</p>
                  <p className="text-gray-300 text-sm mb-3">Date: {receipt.date}</p>
                  <p className="text-blue-300 font-semibold">{receipt.items.length} items</p>
                  <button className="w-full mt-4 bg-green-500 hover:bg-green-600 text-white py-2 rounded-lg font-semibold transition-all">
                    Analyze Receipt →
                  </button>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Processing Steps */}
        {isProcessing && (
          <div className="bg-blue-900/30 rounded-lg p-6">
            <h3 className="text-xl font-bold text-white mb-4">🤖 AI Processing Steps:</h3>
            <div className="space-y-3">
              <div className={`flex items-center ${processingStep >= 1 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{processingStep >= 1 ? '✅' : '⏳'}</span>
                <span>Step 1: Scanning receipt image with OCR technology...</span>
              </div>
              <div className={`flex items-center ${processingStep >= 2 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{processingStep >= 2 ? '✅' : '⏳'}</span>
                <span>Step 2: Extracting items, prices, and quantities...</span>
              </div>
              <div className={`flex items-center ${processingStep >= 3 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{processingStep >= 3 ? '✅' : '⏳'}</span>
                <span>Step 3: Categorizing items using machine learning...</span>
              </div>
              <div className={`flex items-center ${processingStep >= 4 ? 'text-green-400' : 'text-gray-400'}`}>
                <span className="mr-3">{processingStep >= 4 ? '✅' : '⏳'}</span>
                <span>Step 4: Generating expense analysis and insights...</span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Analysis Results */}
      {analysisResults && selectedReceipt && (
        <>
          {/* Receipt Header */}
          <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 mb-6">
            <div className="flex justify-between items-center mb-4">
              <div>
                <h3 className="text-2xl font-bold text-white">{selectedReceipt.name}</h3>
                <p className="text-gray-300">{selectedReceipt.store} • {selectedReceipt.date}</p>
              </div>
              <button
                onClick={() => {
                  setSelectedReceipt(null);
                  setAnalysisResults(null);
                  setProcessingStep(0);
                }}
                className="bg-white/20 hover:bg-white/30 text-white px-4 py-2 rounded-lg transition-all"
              >
                ← Analyze Another
              </button>
            </div>

            <div className="grid grid-cols-3 gap-4 mt-6">
              <div className="bg-blue-900/30 rounded-lg p-4 text-center">
                <div className="text-3xl font-bold text-blue-400">
                  ₹{analysisResults.total.toLocaleString()}
                </div>
                <div className="text-gray-300 mt-1">Total Amount</div>
              </div>
              <div className="bg-purple-900/30 rounded-lg p-4 text-center">
                <div className="text-3xl font-bold text-purple-400">{analysisResults.itemCount}</div>
                <div className="text-gray-300 mt-1">Total Items</div>
              </div>
              <div className="bg-green-900/30 rounded-lg p-4 text-center">
                <div className="text-3xl font-bold text-green-400">
                  ₹{Math.round(analysisResults.avgItemPrice)}
                </div>
                <div className="text-gray-300 mt-1">Avg per Item</div>
              </div>
            </div>
          </div>

          {/* Extracted Items */}
          <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 mb-6">
            <h3 className="text-2xl font-bold text-white mb-4">📦 Extracted Items</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b border-white/20">
                    <th className="py-3 px-4 text-white">#</th>
                    <th className="py-3 px-4 text-white">Item Name</th>
                    <th className="py-3 px-4 text-white">Category</th>
                    <th className="py-3 px-4 text-white">Quantity</th>
                    <th className="py-3 px-4 text-white">Price</th>
                    <th className="py-3 px-4 text-white">Total</th>
                  </tr>
                </thead>
                <tbody>
                  {selectedReceipt.items.map((item, idx) => (
                    <tr key={idx} className="border-b border-white/10 hover:bg-white/5">
                      <td className="py-3 px-4 text-gray-300">{idx + 1}</td>
                      <td className="py-3 px-4 text-white">{item.name}</td>
                      <td className="py-3 px-4">
                        <span className="bg-blue-500/30 text-blue-300 px-3 py-1 rounded-full text-sm">
                          {item.category}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-gray-300">{item.quantity}</td>
                      <td className="py-3 px-4 text-gray-300">₹{item.price}</td>
                      <td className="py-3 px-4 text-white font-semibold">
                        ₹{item.price * item.quantity}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Charts */}
          <div className="grid md:grid-cols-2 gap-6 mb-6">
            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <h3 className="text-2xl font-bold text-white mb-4">📊 Category-wise Spending</h3>
              <Pie data={analysisResults.chartData} options={chartOptions} />
            </div>

            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <h3 className="text-2xl font-bold text-white mb-4">📈 Spending Trends</h3>
              <Bar data={spendingTrends} options={barChartOptions} />
            </div>
          </div>

          {/* Budget Analysis */}
          <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 mb-6">
            <h3 className="text-2xl font-bold text-white mb-4">💰 Budget Analysis</h3>
            <div className="space-y-4">
              {Object.entries(analysisResults.categoryTotals).map(([category, amount]) => {
                const budgetStatus = getBudgetStatus(category, amount);
                return (
                  <div key={category} className="bg-white/5 rounded-lg p-4">
                    <div className="flex justify-between items-center mb-2">
                      <span className="text-white font-semibold">{category}</span>
                      <span className="text-white">₹{amount.toLocaleString()}</span>
                    </div>
                    {budgetStatus && (
                      <>
                        <div className="w-full bg-gray-700 rounded-full h-3 mb-2">
                          <div
                            className={`h-3 rounded-full ${
                              budgetStatus.color === 'green' ? 'bg-green-500' :
                              budgetStatus.color === 'orange' ? 'bg-orange-500' : 'bg-red-500'
                            }`}
                            style={{ width: `${Math.min(budgetStatus.percentage, 100)}%` }}
                          ></div>
                        </div>
                        <div className="flex justify-between text-sm">
                          <span className={`font-semibold ${
                            budgetStatus.color === 'green' ? 'text-green-400' :
                            budgetStatus.color === 'orange' ? 'text-orange-400' : 'text-red-400'
                          }`}>
                            {budgetStatus.status}
                          </span>
                          <span className="text-gray-400">
                            {budgetStatus.percentage.toFixed(0)}% of budget used
                          </span>
                        </div>
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Insights & Recommendations */}
          <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
            <h3 className="text-2xl font-bold text-white mb-4">💡 AI-Powered Insights</h3>
            <div className="grid md:grid-cols-3 gap-4">
              <div className="bg-blue-900/20 rounded-lg p-4">
                <div className="text-3xl mb-2">🎯</div>
                <h4 className="font-bold text-white mb-2">Top Category</h4>
                <p className="text-gray-300">
                  {analysisResults.topCategory} accounts for{' '}
                  {((analysisResults.topCategoryAmount / analysisResults.total) * 100).toFixed(0)}%
                  of total spending
                </p>
              </div>
              <div className="bg-green-900/20 rounded-lg p-4">
                <div className="text-3xl mb-2">💡</div>
                <h4 className="font-bold text-white mb-2">Recommendation</h4>
                <p className="text-gray-300">
                  Consider buying {analysisResults.topCategory.toLowerCase()} items in bulk to save up to 15%
                </p>
              </div>
              <div className="bg-purple-900/20 rounded-lg p-4">
                <div className="text-3xl mb-2">📊</div>
                <h4 className="font-bold text-white mb-2">Savings Tip</h4>
                <p className="text-gray-300">
                  You could save ₹{Math.round(analysisResults.total * 0.12)} by using store loyalty cards
                </p>
              </div>
            </div>
          </div>
        </>
      )}

      {/* Disclaimer */}
      <div className="mt-8 bg-yellow-900/20 border border-yellow-500/50 rounded-lg p-4">
        <p className="text-yellow-200 text-center">
          ⚠️ <strong>Simulation Mode:</strong> All receipts and analysis shown use sample data for demonstration.
          Real implementation would use OCR and computer vision for actual receipt scanning.
        </p>
      </div>
    </div>
  );
}

export default GroceryAnalyzer;
